const DAY_MS = 86400000;
const koreaDay = now => new Date(now + 9 * 3600000).toISOString().slice(0, 10);
const json = (data, status = 200, extra = {}) => Response.json(data, { status, headers: { 'Cache-Control': 'no-store', ...extra } });

async function visitors(request, env, now = Date.now()) {
  const url = new URL(request.url);
  if (request.method !== 'POST') return json({ error: 'method_not_allowed' }, 405, { Allow: 'POST' });
  if (request.headers.get('Origin') !== url.origin || request.headers.get('Sec-Fetch-Site') === 'cross-site') return json({ error: 'forbidden' }, 403);
  if (!env.DB) return json({ error: 'not_connected' }, 503);
  if (/bot|crawler|spider|headless/i.test(request.headers.get('User-Agent') || '')) return json({ error: 'not_counted' }, 403);
  const day = koreaDay(now);
  const cookie = (request.headers.get('Cookie') || '').split(';').map(x => x.trim()).find(x => x.startsWith('donghaeng_visit='))?.slice(16);
  const valid = cookie && new RegExp('^' + day + '\\.[0-9a-f-]{36}$').test(cookie);
  const id = valid ? cookie.slice(11) : crypto.randomUUID();
  const headers = {};
  if (!valid) headers['Set-Cookie'] = `donghaeng_visit=${day}.${id}; Path=/; Secure; HttpOnly; SameSite=Strict; Max-Age=86400`;
  try {
    const result = await env.DB.batch([
      env.DB.prepare('DELETE FROM visits WHERE day < ?').bind(koreaDay(now - DAY_MS)),
      env.DB.prepare('INSERT INTO visits (day, visitor_id, last_seen) VALUES (?, ?, ?) ON CONFLICT(day, visitor_id) DO UPDATE SET last_seen = excluded.last_seen WHERE visits.last_seen < ?').bind(day, id, now, now - 45000),
      env.DB.prepare('SELECT COUNT(*) AS total FROM visits WHERE day = ?').bind(day),
      env.DB.prepare('SELECT COUNT(*) AS total FROM visits WHERE day = ? AND last_seen >= ?').bind(day, now - 120000),
    ]);
    return json({ today: result[2].results[0].total, active: result[3].results[0].total, date: day, timezone: 'Asia/Seoul', windowSeconds: 120, measuredAt: new Date(now).toISOString(), unit: 'anonymous_browser' }, 200, headers);
  } catch {
    return json({ error: 'temporarily_unavailable' }, 503);
  }
}


const SOURCES = [
 {id:'epmc',name:'Europe PMC 공개 논문',interval:3600000,url:'https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=TITLE:%22amyotrophic%20lateral%20sclerosis%22%20AND%20OPEN_ACCESS:Y%20AND%20(randomized%20OR%20randomised)%20sort_date:y&format=json&pageSize=30&resultType=core'},
 {id:'ctgov',name:'ClinicalTrials.gov',interval:3600000,url:'https://clinicaltrials.gov/api/v2/studies?query.cond=amyotrophic%20lateral%20sclerosis&sort=LastUpdatePostDate:desc&pageSize=100&format=json'},
 {id:'kdca',name:'질병관리청 보도자료',interval:3600000,url:'https://www.kdca.go.kr/bbs/kdca/41/rssList.do?row=50'},
];
const als = /amyotrophic lateral sclerosis|루게릭|근위축성\s*측삭|근위축성\s*가쪽/i;
const exclude = /fundrais|donation|charity|stock price|share price|investor|행사|기부|모금|주식|주가|설명회|심포지엄|세미나|캠페인/i;
function cleanText(s){return String(s||'').replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g,'$1').replace(/<[^>]*>/g,' ').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#39;|&apos;/g,"'").replace(/\s+/g,' ').trim()}
function safeSourceUrl(raw,host){try{const u=new URL(raw);return u.protocol==='https:'&&(u.hostname===host||u.hostname.endsWith('.'+host))?u.href:null}catch{return null}}
function parseTrials(data,now=Date.now()){
 if(!Array.isArray(data.studies))throw Error('invalid_ctgov');
 return data.studies.flatMap(s=>{
 const p=s.protocolSection||{},i=p.identificationModule||{},st=p.statusModule||{},d=p.designModule||{},t=cleanText(i.briefTitle),conditions=(p.conditionsModule?.conditions||[]).join(' '),phase=d.phases||[];
 const date=st.lastUpdatePostDateStruct?.date,age=now-Date.parse(date);
 if(!/^NCT\d{8}$/.test(i.nctId)||!als.test(conditions+' '+t)||exclude.test(t)||d.studyType!=='INTERVENTIONAL'||!phase.some(x=>['PHASE2','PHASE3','PHASE4'].includes(x))||!Number.isFinite(age)||age<0||age>45*86400000)return [];
 const countries=[...new Set((p.contactsLocationsModule?.locations||[]).map(l=>l.country).filter(Boolean))];
 return [{source_id:'ctgov',source_key:i.nctId,source_title:t.slice(0,500),source_url:'https://clinicaltrials.gov/study/'+i.nctId,source_date:date,category:'임상',region:countries.includes('South Korea')?'국내':'국외',reason:'2상 이상 중재 임상 등록정보 변경 · 중요성 검토 필요',metadata:JSON.stringify({phase,status:st.overallStatus,countries,excerpt:cleanText(p.descriptionModule?.briefSummary||'').slice(0,400),hasResults:!!s.hasResults}),fingerprint:JSON.stringify([i.nctId,date,st.overallStatus,!!s.hasResults])}];
 });
}
function parseKdca(xml,now=Date.now()){
 if(!/<rss\b|<rdf:RDF\b/i.test(xml))throw Error('invalid_rss');
 if(!/<item\b/i.test(xml))throw Error('upstream_empty_feed_check_required');
 const field=(s,n)=>cleanText(s.match(new RegExp('<'+n+'(?:\\s[^>]*)?>([\\s\\S]*?)</'+n+'>','i'))?.[1]||'');
 return [...xml.matchAll(/<item\b[^>]*>([\s\S]*?)<\/item>/gi)].slice(0,50).flatMap(m=>{
 const s=m[1],title=field(s,'title'),url=safeSourceUrl(field(s,'link'),'kdca.go.kr'),description=field(s,'description'),text=title+' '+description;
 if(!url||exclude.test(title)||!(/루게릭|근위축성|희귀질환/.test(text))||!(/지원|의료비|급여|간병|돌봄|정책|지침|신청|대상|확대|개정/.test(text)))return [];
 const pub=Date.parse(field(s,'pubDate'));if(Number.isFinite(pub)&&(pub>now+86400000||now-pub>90*86400000))return [];
 return [{source_id:'kdca',source_key:url,source_title:title.slice(0,500),source_url:url,source_date:Number.isFinite(pub)?new Date(pub).toISOString().slice(0,10):'',category:'국가정책·지원',region:'국내',reason:'희귀질환 정책·지원 공지 · 루게릭 적용 여부 검토 필요',metadata:'{}',fingerprint:JSON.stringify([url,title,field(s,'pubDate')])}];
 });
}
function parsePapers(data,now=Date.now()){
 if(!Array.isArray(data.resultList?.result))throw Error('invalid_epmc');
 return data.resultList.result.flatMap(p=>{
 const title=cleanText(p.title),date=p.firstPublicationDate,age=now-Date.parse(date);
 if(p.isOpenAccess!=='Y'||!/^PMC\d+$/.test(p.pmcid||'')||!als.test(title)||exclude.test(title)||!Number.isFinite(age)||age<0||age>120*86400000||!/randomi[sz]ed|clinical trial/i.test(title+' '+(p.abstractText||'')))return [];
 return [{source_id:'epmc',source_key:p.pmcid,source_title:title.slice(0,500),source_url:'https://europepmc.org/articles/'+p.pmcid,source_date:date,category:'임상',region:'국외',reason:'공개 임상 관련 논문 후보 · 연구 유형·결과 원문 검토 필요',metadata:JSON.stringify({journal:p.journalInfo?.journal?.title||'',doi:p.doi||'',excerpt:cleanText(p.abstractText||'').slice(0,400),access:'Open access metadata; full paper needs review'}),fingerprint:JSON.stringify([p.pmcid,date,title])}];
 });
}
async function fetchSource(url,headers,fetcher){
 const origin=new URL(url).origin;
 const signal=AbortSignal.timeout(20000);
 for(let hop=0;hop<4;hop++){
 const response=await fetcher(url,{headers,redirect:'manual',signal});
 if(![301,302,303,307,308].includes(response.status))return response;
 const location=response.headers.get('Location');
 if(response.body)await response.body.cancel();
 if(!location)throw Error('redirect_without_location');
 const next=new URL(location,url);
 if(next.origin!==origin)throw Error('redirect_origin_changed');
 url=next.href;
 }
 throw Error('too_many_redirects');
}
async function collect(env,now=Date.now(),fetcher=fetch){
 if(!env.DB)throw Error('database_not_connected');await ensureExtras(env);const report=[];
 // One-time recovery from the unsupported redirect option in older deployments.
 await env.DB.prepare("UPDATE source_state SET next_run=0,last_error=NULL WHERE last_error LIKE 'Invalid redirect value%'").run();
 for(const source of SOURCES){
 // Atomic lease prevents concurrent scheduled/manual calls from duplicating a run.
 await env.DB.prepare('INSERT OR IGNORE INTO source_state (id,next_run) VALUES (?,0)').bind(source.id).run();
 const lease=await env.DB.prepare('UPDATE source_state SET next_run=? WHERE id=? AND next_run<=?').bind((Math.floor(now/source.interval)+1)*source.interval,source.id,now).run();
 if(!lease.meta?.changes){report.push({id:source.id,status:'not_due'});continue}
 const prior=await env.DB.prepare('SELECT etag,last_modified FROM source_state WHERE id=?').bind(source.id).first();
 try{
 const headers={'User-Agent':'ALS-Donghaeng/1.0 (public research and policy feed)','Accept':source.id!=='kdca'?'application/json':'application/rss+xml, application/xml, text/xml'};
 if(prior?.etag)headers['If-None-Match']=prior.etag;if(prior?.last_modified)headers['If-Modified-Since']=prior.last_modified;
 const response=await fetchSource(source.url,headers,fetcher);
 if(response.status===304){await env.DB.prepare("UPDATE source_state SET last_check=?,last_success=?,last_error=NULL WHERE id=?").bind(now,now,source.id).run();report.push({id:source.id,status:'unchanged'});continue}
 if(!response.ok)throw Error('HTTP_'+response.status);
 const declared=Number(response.headers.get('Content-Length')||0);if(declared>6000000)throw Error('response_too_large');
 const reader=response.body.getReader();let length=0;const chunks=[];while(true){const {done,value}=await reader.read();if(done)break;length+=value.length;if(length>6000000){await reader.cancel();throw Error('response_too_large')}chunks.push(value)}
 const buffer=new Uint8Array(length);let pos=0;for(const c of chunks){buffer.set(c,pos);pos+=c.length}const text=new TextDecoder().decode(buffer);
 const candidates=source.id==='ctgov'?parseTrials(JSON.parse(text),now):source.id==='epmc'?parsePapers(JSON.parse(text),now):parseKdca(text,now);let added=0;
 for(const c of candidates){
 const old=await env.DB.prepare('SELECT fingerprint FROM candidates WHERE source_id=? AND source_key=?').bind(c.source_id,c.source_key).first();
 if(old?.fingerprint===c.fingerprint)continue;
 await env.DB.prepare("INSERT INTO candidates (id,source_id,source_key,source_title,source_url,source_date,category,region,reason,metadata,fingerprint,status,seen_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,'pending',?) ON CONFLICT(source_id,source_key) DO UPDATE SET source_title=excluded.source_title,source_date=excluded.source_date,metadata=excluded.metadata,fingerprint=excluded.fingerprint,status='pending',seen_at=excluded.seen_at").bind(source.id+'-'+crypto.randomUUID(),c.source_id,c.source_key,c.source_title,c.source_url,c.source_date,c.category,c.region,c.reason,c.metadata,c.fingerprint,now).run();added++;
 }
 await env.DB.prepare('UPDATE source_state SET last_check=?,last_success=?,last_error=NULL,etag=?,last_modified=?,last_count=? WHERE id=?').bind(now,now,response.headers.get('ETag'),response.headers.get('Last-Modified'),added,source.id).run();report.push({id:source.id,status:'ok',queued:added});
 }catch(e){const error=String(e.message).slice(0,150);await env.DB.prepare('UPDATE source_state SET last_check=?,last_error=?,next_run=? WHERE id=?').bind(now,error,now+60000,source.id).run();report.push({id:source.id,status:'error',error})}
 }
 report.push({id:'translation',...await translatePending(env,now)});
 return report;
}


const TRANSLATION_MODEL='@cf/meta/m2m100-1.2b';
async function ensureExtras(env){
 await env.DB.batch([
 env.DB.prepare('CREATE TABLE IF NOT EXISTS app_state (id TEXT PRIMARY KEY,value TEXT)'),
 env.DB.prepare('CREATE TABLE IF NOT EXISTS translation_cache (hash TEXT PRIMARY KEY,text TEXT NOT NULL,created_at INTEGER NOT NULL)'),
 env.DB.prepare('CREATE TABLE IF NOT EXISTS translation_budget (day TEXT PRIMARY KEY,calls INTEGER NOT NULL DEFAULT 0,chars INTEGER NOT NULL DEFAULT 0)'),
 env.DB.prepare('CREATE TABLE IF NOT EXISTS candidate_translations (candidate_id TEXT PRIMARY KEY,fingerprint TEXT NOT NULL,title TEXT,summary TEXT,state TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,retry_at INTEGER NOT NULL DEFAULT 0)')
 ]);
}
async function stateSet(env,id,value){await env.DB.prepare('INSERT INTO app_state(id,value) VALUES (?,?) ON CONFLICT(id) DO UPDATE SET value=excluded.value').bind(id,JSON.stringify(value)).run()}
async function translateText(env,text,now){
 text=cleanText(text).slice(0,400);if(!text)return '';
 const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(TRANSLATION_MODEL+'|en|ko|'+text));
 const hash=Array.from(new Uint8Array(bytes),x=>x.toString(16).padStart(2,'0')).join('');
 const cached=await env.DB.prepare('SELECT text FROM translation_cache WHERE hash=?').bind(hash).first();if(cached)return cached.text;
 const day=new Date(now).toISOString().slice(0,10);
 await env.DB.prepare('INSERT OR IGNORE INTO translation_budget(day) VALUES (?)').bind(day).run();
 const reserved=await env.DB.prepare('UPDATE translation_budget SET calls=calls+1,chars=chars+? WHERE day=? AND calls<20 AND chars+?<=8000').bind(text.length,day,text.length).run();
 if(!reserved.meta?.changes)throw Error('daily_limit');
 const result=await env.AI.run(TRANSLATION_MODEL,{text,source_lang:'en',target_lang:'ko'});
 const translated=result?.translated_text;
 if(typeof translated!=='string'||!translated.trim()||translated.length>1500||!/[가-힣]/.test(translated))throw Error('translation_failed');
 await env.DB.prepare('INSERT OR IGNORE INTO translation_cache(hash,text,created_at) VALUES (?,?,?)').bind(hash,translated,now).run();return translated;
}
async function translatePending(env,now=Date.now()){
 if(!env.AI){await stateSet(env,'translation',{status:'not_connected',at:now});return {status:'not_connected'}}
 await env.DB.prepare("INSERT OR IGNORE INTO app_state(id,value) VALUES ('translation_lock','0')").run();
 const lock=await env.DB.prepare("UPDATE app_state SET value=? WHERE id='translation_lock' AND CAST(value AS INTEGER)<=?").bind(String(now+600000),now).run();
 if(!lock.meta?.changes)return {status:'running'};
 let completed=0,status='ok';
 try{
 const rows=await env.DB.prepare("SELECT c.*,t.attempts AS tries FROM candidates c LEFT JOIN candidate_translations t ON t.candidate_id=c.id WHERE c.status='pending' AND c.source_id IN ('ctgov','epmc') AND (t.candidate_id IS NULL OR t.fingerprint<>c.fingerprint OR (t.state<>'ready' AND t.retry_at<=? AND t.attempts<3)) ORDER BY c.seen_at DESC LIMIT 4").bind(now).all();
 for(const c of rows.results){
 let title='',summary='';
 try{
 title=await translateText(env,c.source_title,now);
 const meta=JSON.parse(c.metadata||'{}');summary=await translateText(env,meta.excerpt||'',now);
 await env.DB.prepare("INSERT INTO candidate_translations(candidate_id,fingerprint,title,summary,state,attempts,retry_at) VALUES (?,?,?,?,'ready',0,0) ON CONFLICT(candidate_id) DO UPDATE SET fingerprint=excluded.fingerprint,title=excluded.title,summary=excluded.summary,state='ready',attempts=0,retry_at=0").bind(c.id,c.fingerprint,title,summary).run();completed++;
 }catch(e){
 status=e.message==='daily_limit'?'daily_limit':'translation_error';
 if(status==='daily_limit')break;
 await env.DB.prepare("INSERT INTO candidate_translations(candidate_id,fingerprint,state,attempts,retry_at) VALUES (?,?,'error',1,?) ON CONFLICT(candidate_id) DO UPDATE SET fingerprint=excluded.fingerprint,state='error',attempts=CASE WHEN candidate_translations.fingerprint=excluded.fingerprint THEN candidate_translations.attempts+1 ELSE 1 END,retry_at=excluded.retry_at").bind(c.id,c.fingerprint,now+3600000).run();
 // Stop on provider errors, including a provider quota rejection.
 break;
 }
 }
 await stateSet(env,'translation',{status,completed,at:now});return {status,completed};
 }finally{await env.DB.prepare("UPDATE app_state SET value='0' WHERE id='translation_lock'").run()}
}
async function statusInfo(env){
 const sources=(await env.DB.prepare('SELECT * FROM source_state').all()).results;
 let state={};try{state=Object.fromEntries((await env.DB.prepare('SELECT id,value FROM app_state').all()).results.map(r=>[r.id,JSON.parse(r.value)]))}catch{}
 return {connected:true,aiConnected:!!env.AI,adminConfigured:!!env.ADMIN_KEY&&env.ADMIN_KEY.length>=32,lastScheduled:state.lastScheduled||null,translation:state.translation||null,sources:sources.map(s=>({...s,name:SOURCES.find(x=>x.id===s.id)?.name||s.id})),intervalMinutes:60};
}

